-- Definitions from the linked project; no user data.
alter table academy_settings add constraint academy_settings_pkey PRIMARY KEY (id);
alter table attendance add constraint attendance_pkey PRIMARY KEY (id);
alter table audit_logs add constraint audit_logs_pkey PRIMARY KEY (id);
alter table login_audit_logs add constraint login_audit_logs_pkey PRIMARY KEY (id);
alter table matches add constraint matches_pkey PRIMARY KEY (id);
alter table notifications add constraint notifications_pkey PRIMARY KEY (id);
alter table parents add constraint parents_pkey PRIMARY KEY (id);
alter table player_documents add constraint player_documents_pkey PRIMARY KEY (id);
alter table players add constraint players_pkey PRIMARY KEY (id);
alter table registration_applications add constraint registration_applications_pkey PRIMARY KEY (id);
alter table registration_children add constraint registration_children_pkey PRIMARY KEY (id);
alter table registration_documents add constraint registration_documents_pkey PRIMARY KEY (id);
alter table some_table add constraint some_table_pkey PRIMARY KEY (id);
alter table staff add constraint staff_pkey PRIMARY KEY (id);
alter table subscriptions add constraint subscriptions_pkey PRIMARY KEY (id);
alter table teams add constraint teams_pkey PRIMARY KEY (id);
alter table tournaments add constraint tournaments_pkey PRIMARY KEY (id);
alter table trainings add constraint trainings_pkey PRIMARY KEY (id);
alter table transactions add constraint transactions_pkey PRIMARY KEY (id);
alter table videos add constraint videos_pkey PRIMARY KEY (id);
alter table academy_settings add constraint chk_academy_settings_semi_annual_nonnegative CHECK ((subscription_fee_semi_annual >= (0)::numeric));
alter table attendance add constraint chk_attendance_status CHECK ((status = ANY (ARRAY['present'::text, 'absent'::text, 'excused'::text])));
alter table matches add constraint chk_matches_result_valid CHECK ((result = ANY (ARRAY['scheduled'::text, 'win'::text, 'draw'::text, 'loss'::text, 'cancelled'::text, 'postponed'::text])));
alter table matches add constraint chk_matches_scores_nonnegative CHECK (((academy_score >= 0) AND (opponent_score >= 0)));
alter table player_documents add constraint chk_player_documents_photo_mime CHECK (((file_category <> 'photo'::text) OR (file_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))));
alter table player_documents add constraint chk_player_documents_size_nonnegative CHECK ((file_size >= 0));
alter table players add constraint chk_players_birth_before_joined CHECK ((birth_date <= joined_date));
alter table players add constraint chk_players_jersey_nonneg CHECK ((jersey_number >= 0));
alter table players add constraint chk_players_status CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'suspended'::text])));
alter table registration_applications add constraint chk_registration_application_status CHECK ((status = ANY (ARRAY['draft'::text, 'pending'::text, 'under_review'::text, 'needs_info'::text, 'approved'::text, 'rejected'::text])));
alter table registration_children add constraint chk_registration_child_birth_date CHECK ((birth_date <= CURRENT_DATE));
alter table registration_children add constraint chk_registration_child_cpr CHECK ((length(TRIM(BOTH FROM national_id)) > 0));
alter table registration_children add constraint chk_registration_child_name CHECK ((length(TRIM(BOTH FROM full_name)) >= 2));
alter table registration_documents add constraint chk_registration_document_category CHECK ((file_category = ANY (ARRAY['photo'::text, 'document'::text])));
alter table registration_documents add constraint chk_registration_document_size CHECK ((file_size >= 0));
alter table registration_applications add constraint chk_registration_parent_cpr CHECK ((length(TRIM(BOTH FROM parent_national_id)) > 0));
alter table registration_applications add constraint chk_registration_parent_email CHECK ((POSITION(('@'::text) IN (parent_email)) > 1));
alter table registration_applications add constraint chk_registration_parent_name CHECK ((length(TRIM(BOTH FROM parent_full_name)) >= 2));
alter table registration_applications add constraint chk_registration_parent_phone CHECK ((length(TRIM(BOTH FROM parent_phone)) > 0));
alter table registration_documents add constraint chk_registration_photo_child CHECK (((file_category <> 'photo'::text) OR (child_id IS NOT NULL)));
alter table registration_documents add constraint chk_registration_photo_mime CHECK (((file_category <> 'photo'::text) OR (mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))));
alter table staff add constraint chk_staff_experience_nonnegative CHECK (((experience_years IS NULL) OR (experience_years >= 0)));
alter table staff add constraint chk_staff_rating_range CHECK (((rating IS NULL) OR ((rating >= (0)::numeric) AND (rating <= (5)::numeric))));
alter table staff add constraint chk_staff_role_valid CHECK ((role = ANY (ARRAY['manager'::text, 'accountant'::text, 'coach'::text, 'receptionist'::text])));
alter table staff add constraint chk_staff_salary_nonneg CHECK ((salary >= (0)::numeric));
alter table staff add constraint chk_staff_status_valid CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'pending'::text])));
alter table subscriptions add constraint chk_subscriptions_amount_positive CHECK ((amount > (0)::numeric));
alter table subscriptions add constraint chk_subscriptions_date_range CHECK ((end_date >= start_date));
alter table subscriptions add constraint chk_subscriptions_paid_consistency CHECK ((((status = 'paid'::text) AND (paid_at IS NOT NULL) AND (COALESCE(payment_method, ''::text) <> ''::text)) OR ((status = 'unpaid'::text) AND (paid_at IS NULL))));
alter table subscriptions add constraint chk_subscriptions_plan_type CHECK ((plan_type = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'semi_annual'::text, 'annual'::text])));
alter table subscriptions add constraint chk_subscriptions_status CHECK ((status = ANY (ARRAY['unpaid'::text, 'paid'::text])));
alter table tournaments add constraint chk_tournaments_date_range CHECK ((end_date >= start_date));
alter table tournaments add constraint chk_tournaments_teams_count_nonnegative CHECK ((teams_count >= 0));
alter table trainings add constraint chk_trainings_duration_positive CHECK (((duration_minutes > 0) AND (duration_minutes <= 480)));
alter table transactions add constraint chk_transactions_amount_positive CHECK ((amount >= (0)::numeric));
alter table transactions add constraint chk_transactions_type CHECK ((type = ANY (ARRAY['revenue'::text, 'expense'::text])));
alter table matches add constraint matches_result_score_consistency CHECK ((((lower(TRIM(BOTH FROM result)) = ANY (ARRAY['win'::text, 'won'::text, 'فوز'::text])) AND (academy_score > opponent_score)) OR ((lower(TRIM(BOTH FROM result)) = ANY (ARRAY['draw'::text, 'تعادل'::text])) AND (academy_score = opponent_score)) OR ((lower(TRIM(BOTH FROM result)) = ANY (ARRAY['loss'::text, 'lose'::text, 'lost'::text, 'خسارة'::text])) AND (academy_score < opponent_score)) OR ((lower(TRIM(BOTH FROM result)) = ANY (ARRAY['scheduled'::text, 'cancelled'::text, 'canceled'::text, 'postponed'::text, 'ملغاة'::text, 'مؤجلة'::text])) AND (academy_score = 0) AND (opponent_score = 0))));
alter table notifications add constraint notifications_message_nonempty_chk CHECK ((length(TRIM(BOTH FROM message)) > 0));
alter table notifications add constraint notifications_title_nonempty_chk CHECK ((length(TRIM(BOTH FROM title)) > 0));
alter table attendance add constraint fk_attendance_player_id FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE SET NULL;
alter table attendance add constraint fk_attendance_training_id FOREIGN KEY (training_id) REFERENCES trainings(id) ON DELETE SET NULL;
alter table matches add constraint fk_matches_team_id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE SET NULL;
alter table player_documents add constraint fk_player_documents_player_id FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE;
alter table players add constraint fk_players_parent_id FOREIGN KEY (parent_id) REFERENCES parents(id) ON DELETE SET NULL;
alter table players add constraint fk_players_team_id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE RESTRICT;
alter table staff add constraint fk_staff_user_id FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;
alter table subscriptions add constraint fk_subscriptions_player_id FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE SET NULL;
alter table teams add constraint fk_teams_coach_id FOREIGN KEY (coach_id) REFERENCES staff(id) ON DELETE RESTRICT;
alter table trainings add constraint fk_trainings_team_id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE SET NULL;
alter table transactions add constraint fk_transactions_player_id FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE SET NULL;
alter table transactions add constraint fk_transactions_subscription_id FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL;
alter table notifications add constraint notifications_recipient_user_id_fkey FOREIGN KEY (recipient_user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table parents add constraint parents_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;
alter table registration_applications add constraint registration_applications_applicant_user_id_fkey FOREIGN KEY (applicant_user_id) REFERENCES auth.users(id) ON DELETE SET NULL;
alter table registration_applications add constraint registration_applications_approved_parent_id_fkey FOREIGN KEY (approved_parent_id) REFERENCES parents(id) ON DELETE SET NULL;
alter table registration_applications add constraint registration_applications_reviewed_by_staff_id_fkey FOREIGN KEY (reviewed_by_staff_id) REFERENCES staff(id) ON DELETE SET NULL;
alter table registration_children add constraint registration_children_application_id_fkey FOREIGN KEY (application_id) REFERENCES registration_applications(id) ON DELETE CASCADE;
alter table registration_children add constraint registration_children_approved_player_id_fkey FOREIGN KEY (approved_player_id) REFERENCES players(id) ON DELETE SET NULL;
alter table registration_documents add constraint registration_documents_application_id_fkey FOREIGN KEY (application_id) REFERENCES registration_applications(id) ON DELETE CASCADE;
alter table registration_documents add constraint registration_documents_approved_player_id_fkey FOREIGN KEY (approved_player_id) REFERENCES players(id) ON DELETE SET NULL;
alter table registration_documents add constraint registration_documents_child_id_fkey FOREIGN KEY (child_id) REFERENCES registration_children(id) ON DELETE CASCADE;